@pyqtSlot(str)
def add_log(self, text):
    """线程安全入队；可从主线程直接调用，仅持锁追加，不阻塞磁盘 I/O。"""
    with self.lock:
        self.queue.append(text)

@pyqtSlot()
def process(self):
    while self.running:
        texts = None
        with self.lock:
            if self.queue:
                batch = BATCH_SIZE * 2 if len(self.queue) > BATCH_SIZE * 4 else BATCH_SIZE
                texts = self.queue[:batch]
                self.queue = self.queue[batch:]
        if texts:
            try:
                LocalLogSetting.appendToLogList(texts)
            except Exception as e:
                print(f'Log write error: {e}')
        queue_len = 0
        with self.lock:
            queue_len = len(self.queue)
        QThread.msleep(20 if queue_len > BATCH_SIZE * 4 else 50 if queue_len > BATCH_SIZE else 200)
    with self.lock:
        remaining_logs = self.queue.copy()
        self.queue.clear()
    if remaining_logs:
        try:
            LocalLogSetting.appendToLogList(remaining_logs)
        except Exception:
            pass
    self.finished.emit()

@pyqtSlot(object, str)
def _deliver(self, status: AiTextGenStatus, output_text: str):
    self._tab._apply_ai_test_finish(status, output_text)

